import{_ as e,c as o,o as a,am as s}from"./chunks/framework.1_Rjriwz.js";const m=JSON.parse('{"title":"映射收纳和普通收纳","description":"","frontmatter":{"prev":false,"next":{"text":"组件编组","link":"/docs/pogget/group"}},"headers":[],"relativePath":"docs/pogget/mapping.md","filePath":"docs/pogget/mapping.md"}'),p={name:"docs/pogget/mapping.md"};function c(r,t,i,l,n,d){return a(),o("div",null,t[0]||(t[0]=[s('<h1 id="映射收纳和普通收纳" tabindex="-1">映射收纳和普通收纳 <a class="header-anchor" href="#映射收纳和普通收纳" aria-label="Permalink to &quot;映射收纳和普通收纳&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">提示 映射收纳盒和普通收纳盒的标题有粗细之分。映射收纳盒为细体标题，普通收纳盒(包括目标收纳盒)为粗体+斜体标题 :::</p><hr><p>映射收纳类似于文件的&quot;镜像&quot;，或者说在收纳盒内添加了文件的快捷方式。 您打开文件后所做的修改会被应用到文件，但&quot;删除&quot;操作仅会删除这个&quot;快捷方式&quot;而非文件本身。 <img src="https://github.com/user-attachments/assets/0a123f4e-b054-444d-b5d3-c562f652feee" alt="explorer_CigyCVECUz"></p><hr><div class="tip custom-block"><p class="custom-block-title">提示 为了防止误删，删除组件时默认选项为&quot;解散并归位&quot;，文件会被放回到原始的位置。如果无法找到原始位置，文件会被放置到桌面。 :::</p><p>物理收纳盒是物理意义上的收纳盒，适用于文件整理等情景。文件会被移动进入收纳盒中，&quot;删除&quot;等操作会真的将文件从电脑上移除。 <img src="https://github.com/user-attachments/assets/59dba52f-41b2-4379-8e73-b95f383d73a5" alt="explorer_CrnlQT9ilq"></p></div></div>',2)]))}const _=e(p,[["render",c]]);export{m as __pageData,_ as default};
